 86	  async getLeadById({
 87	    id,
 88	    orgId,
 89	  }: {
 90	    id: string;
 91	    orgId: string;
 92	  }): Promise<SmartleadOpportunity> {
 93	    const lead = await this.datastoreService.getById({
 94	      id,
 95	      documentType: documentType.SMARTLEAD_OPPORTUNITY,
 96	    });
 97	    if (lead?.data && lead?.data?.orgId !== orgId) {
 98	      throw new NotFoundException('Lead not found');
 99	    } else if (!lead?.data) {
100	      throw new NotFoundException('Lead not found');
101	    }
102	    return lead.data;
103	  }
