349	  async migrate(SOURCE_COLLECTION, TARGET_COLLECTION) {
350	    try {
351	      const sourceCollection = this.db.collection(SOURCE_COLLECTION);
352	      const targetCollection = this.db.collection(TARGET_COLLECTION);
353	
354	      // Process documents in the source collection
355	      const cursor = sourceCollection.find();
356	      const BATCH_SIZE = 1000;
357	      let batch = [];
358	      let processedCount = 0;
359	
360	      while (await cursor.hasNext()) {
361	        const doc = await cursor.next();
362	
363	        // Transform campaignIds to the new format
364	        if (doc.data && doc.data.campaignIds) {
365	          const newDocument = {
366	            ...doc,
367	            data: {
