374	                  ...value,
375	                }),
376	              ),
377	            },
378	          };
379	
380	          // Remove the _id field to avoid duplicate key errors in the new collection
381	          delete newDocument._id;
382	          batch.push(newDocument);
383	
384	          // Insert batch when full
385	          if (batch.length === BATCH_SIZE) {
386	            await targetCollection.insertMany(batch);
387	            processedCount += batch.length;
388	            this.logger.log(`Inserted ${processedCount} documents so far`);
389	            batch = [];
390	          }
391	        } else {
