394	          );
395	        }
396	      }
397	
398	      // Insert remaining documents
399	      if (batch.length > 0) {
400	        await targetCollection.insertMany(batch);
401	        processedCount += batch.length;
402	      }
403	
404	      this.logger.log(
405	        `Transformation completed. Inserted ${processedCount} documents into ${TARGET_COLLECTION}.`,
406	      );
