import { Logger, NotFoundException } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';

/**
 * Deliverability buckets for a warmed inbox.
 *
 * A deliverability score of:
 *  - 100      => High
 *  - 98 - 99  => Medium
 *  - 95 - 97  => Low
 *  - < 95     => Burned
 *  - missing  => Unknown
 */
export enum Deliverability {
  High = 'High',
  Medium = 'Medium',
  Low = 'Low',
  Burned = 'Burned',
  Unknown = 'Unknown',
}

// Aliases kept so consumers can import whichever name reads best at the call site.
export const EmailAccountDeliverability = Deliverability;
export const DeliverabilityStatus = Deliverability;
export type DeliverabilityStatus = Deliverability;
export type EmailAccountDeliverability = Deliverability;

export const SMARTLEAD_API_BASE_URL = 'https://server.smartlead.ai/api/v1';

/**
 * The default assumptions used when sizing the inbox pool for a campaign.
 */
export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
export const DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY = 20;

export type SmartleadRemoteInbox = {
  id?: number | string;
  from_name?: string;
  from_email?: string;
  client_id?: number | string;
  created_at?: string;
  message_per_day?: number;
  tags?: Array<string | { id?: string; name?: string }>;
  warmup_details?: {
    id?: number | string;
    status?: string;
    total_sent_count?: number;
    total_spam_count?: number;
    warmup_reputation?: string | number;
  };
};

const DERIVED_KEYS = [
  'domain',
  'numberOfCampaignAssociated',
  'deliverability',
  'deliverabilityStatus',
  'id',
];

/**
 * An email account (a.k.a. inbox) living inside of Smartlead which we can
 * attach to a campaign once it has been warmed up.
 *
 * The account is keyed by its Smartlead inbox id, it remembers which Smartlead
 * client it belongs to, its email address, the domain that email lives on, any
 * tags it was imported with and every campaign it has been associated with.
 */
export class EmailAccount {
  protected static logger = new Logger(EmailAccount.name);

  /** Smartlead's identifier for the inbox. This is the primary key. */
  public smartleadInboxId: string;
  /** The Smartlead client (customer) the inbox belongs to. */
  public smartleadClientId?: string;
  /** The email address of the inbox. */
  public email?: string;
  /** Free form tags, usually imported alongside the inbox. */
  public tags: string[];
  /** Every campaign this inbox has been associated with. */
  public campaignIds: string[];
  /** When the inbox was created inside of Smartlead. */
  public createdAt?: string;
  /** The warm up reputation reported by Smartlead, expressed as 0 - 100. */
  public warmupReputation?: number;
  /** Number of emails Smartlead is willing to send per day for this inbox. */
  public messagePerDay?: number;

  constructor(partial: Partial<EmailAccount> = {}) {
    const data: Record<string, any> = { ...(partial || {}) };
    // The derived values below are exposed as (enumerable) getters so that they
    // are persisted/serialised, which means we have to make sure we never try
    // to assign over them when re-hydrating a stored document.
    DERIVED_KEYS.forEach((key) => delete data[key]);

    Object.assign(this, data);

    if (
      this.smartleadInboxId !== undefined &&
      this.smartleadInboxId !== null &&
      typeof this.smartleadInboxId !== 'string'
    ) {
      this.smartleadInboxId = String(this.smartleadInboxId);
    }
    if (
      this.smartleadClientId !== undefined &&
      this.smartleadClientId !== null &&
      typeof this.smartleadClientId !== 'string'
    ) {
      this.smartleadClientId = String(this.smartleadClientId);
    }
    if (typeof this.email === 'string') {
      this.email = this.email.trim();
    }
    this.tags = EmailAccount.normalizeTags(
      (partial as Partial<EmailAccount>)?.tags,
    );
    this.campaignIds = EmailAccount.normalizeCampaignIds(
      (partial as Partial<EmailAccount>)?.campaignIds,
    );
    this.warmupReputation = EmailAccount.parseDeliverabilityScore(
      (partial as Partial<EmailAccount>)?.warmupReputation,
    );

    this.defineDerivedProperties();
  }

  private defineDerivedProperties() {
    const self = this;
    Object.defineProperty(this, 'domain', {
      enumerable: true,
      configurable: true,
      get: () => EmailAccount.deriveDomain(self.email),
    });
    Object.defineProperty(this, 'numberOfCampaignAssociated', {
      enumerable: true,
      configurable: true,
      get: () => (self.campaignIds ? self.campaignIds.length : 0),
    });
    Object.defineProperty(this, 'deliverability', {
      enumerable: true,
      configurable: true,
      get: () => EmailAccount.mapDeliverability(self.deliverabilityScore),
    });
    Object.defineProperty(this, 'deliverabilityStatus', {
      enumerable: true,
      configurable: true,
      get: () => EmailAccount.mapDeliverability(self.deliverabilityScore),
    });
  }

  /** The domain the inbox sends from, derived from the email address. */
  public readonly domain?: string;
  /** How many campaigns this inbox is currently associated with. */
  public readonly numberOfCampaignAssociated: number;
  /** The deliverability bucket derived from the deliverability score. */
  public readonly deliverability: Deliverability;
  /** Alias of {@link deliverability}. */
  public readonly deliverabilityStatus: Deliverability;

  /** Alias of {@link smartleadInboxId} so the entity plays nice with the datastore. */
  get id(): string {
    return this.smartleadInboxId;
  }

  /**
   * The deliverability score of the inbox (0 - 100). Smartlead reports this as
   * the warm up reputation of the inbox.
   */
  get deliverabilityScore(): number | undefined {
    return this.warmupReputation;
  }

  set deliverabilityScore(score: number | string | undefined) {
    this.warmupReputation = EmailAccount.parseDeliverabilityScore(score);
  }

  // ---------------------------------------------------------------------------
  // Pure helpers
  // ---------------------------------------------------------------------------

  public static normalizeTags(tags?: any): string[] {
    if (!tags) {
      return [];
    }
    const list = Array.isArray(tags) ? tags : [tags];
    return list
      .map((tag) => {
        if (tag === null || tag === undefined) {
          return null;
        }
        if (typeof tag === 'string') {
          return tag;
        }
        if (typeof tag === 'object') {
          return tag?.name ?? tag?.tag ?? tag?.id ?? null;
        }
        return String(tag);
      })
      .filter((tag) => typeof tag === 'string' && tag.length > 0)
      .filter((tag, index, all) => all.indexOf(tag) === index) as string[];
  }

  public static normalizeCampaignIds(campaignIds?: any): string[] {
    if (!campaignIds) {
      return [];
    }
    const list = Array.isArray(campaignIds) ? campaignIds : [campaignIds];
    return list
      .map((campaignId) => {
        if (campaignId === null || campaignId === undefined) {
          return null;
        }
        if (typeof campaignId === 'object') {
          return campaignId?.id ?? campaignId?.campaignId ?? null;
        }
        return String(campaignId);
      })
      .filter((campaignId) => typeof campaignId === 'string' && campaignId)
      .filter((id, index, all) => all.indexOf(id) === index) as string[];
  }

  /**
   * Derives the sending domain from an email address.
   */
  public static deriveDomain(email?: string): string | undefined {
    if (!email || typeof email !== 'string') {
      return undefined;
    }
    const trimmed = email.trim().toLowerCase();
    const atIndex = trimmed.lastIndexOf('@');
    if (atIndex === -1) {
      return undefined;
    }
    const domain = trimmed.slice(atIndex + 1);
    return domain.length > 0 ? domain : undefined;
  }

  /**
   * Smartlead reports the warm up reputation as either a number or a string
   * such as `"100%"`. Anything we cannot make sense of becomes `undefined` so
   * that it maps onto {@link Deliverability.Unknown}.
   */
  public static parseDeliverabilityScore(
    score?: number | string | null,
  ): number | undefined {
    if (score === null || score === undefined) {
      return undefined;
    }
    if (typeof score === 'number') {
      return Number.isFinite(score) ? score : undefined;
    }
    const cleaned = String(score).replace('%', '').trim();
    if (!cleaned.length) {
      return undefined;
    }
    const parsed = Number(cleaned);
    return Number.isFinite(parsed) ? parsed : undefined;
  }

  /**
   * Maps a deliverability score onto a {@link Deliverability} bucket.
   */
  public static mapDeliverability(
    score?: number | string | null,
  ): Deliverability {
    const parsed = EmailAccount.parseDeliverabilityScore(score);
    if (parsed === undefined) {
      return Deliverability.Unknown;
    }
    if (parsed >= 100) {
      return Deliverability.High;
    }
    if (parsed >= 98) {
      return Deliverability.Medium;
    }
    if (parsed >= 95) {
      return Deliverability.Low;
    }
    return Deliverability.Burned;
  }

  /**
   * How many inboxes are required to send `totalNumberOfEmailsToSend` emails
   * over `numberOfDaysInCampaign` days when a single inbox can only send
   * `numberOfEmailsPerInboxPerDay` emails a day.
   */
  public static calculateNumberOfInboxesRequired({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: {
    totalNumberOfEmailsToSend: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const total = Number(totalNumberOfEmailsToSend);
    const days = Number(
      numberOfDaysInCampaign || DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    );
    const perInboxPerDay = Number(
      numberOfEmailsPerInboxPerDay || DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
    );
    if (!Number.isFinite(total) || total <= 0) {
      return 0;
    }
    if (!Number.isFinite(days) || days <= 0) {
      return 0;
    }
    if (!Number.isFinite(perInboxPerDay) || perInboxPerDay <= 0) {
      return 0;
    }
    return Math.floor(total / days / perInboxPerDay);
  }

  private static createdAtTime(account: EmailAccount): number {
    const time = new Date(account?.createdAt ?? '').getTime();
    // Inboxes without a creation date are considered the newest so that older,
    // proven inboxes are always preferred.
    return Number.isFinite(time) && !Number.isNaN(time)
      ? time
      : Number.MAX_SAFE_INTEGER;
  }

  /**
   * Ranks inboxes so the best candidates for a campaign come first:
   *  1. highest deliverability score first
   *  2. fewest campaigns already associated first
   *  3. fewest sibling inboxes on the same domain first
   *  4. oldest inbox first
   */
  public static rankByBestFit(accounts: EmailAccount[]): EmailAccount[] {
    const pool = (accounts ?? []).filter(Boolean);
    const inboxesPerDomain = pool.reduce<Record<string, number>>(
      (acc, account) => {
        const domain = account?.domain ?? '';
        acc[domain] = (acc[domain] ?? 0) + 1;
        return acc;
      },
      {},
    );
    const siblingsOnDomain = (account: EmailAccount) =>
      Math.max((inboxesPerDomain[account?.domain ?? ''] ?? 1) - 1, 0);

    return [...pool].sort((a, b) => {
      const scoreA = a?.deliverabilityScore ?? -1;
      const scoreB = b?.deliverabilityScore ?? -1;
      if (scoreA !== scoreB) {
        return scoreB - scoreA;
      }
      const campaignsA = a?.numberOfCampaignAssociated ?? 0;
      const campaignsB = b?.numberOfCampaignAssociated ?? 0;
      if (campaignsA !== campaignsB) {
        return campaignsA - campaignsB;
      }
      const domainA = siblingsOnDomain(a);
      const domainB = siblingsOnDomain(b);
      if (domainA !== domainB) {
        return domainA - domainB;
      }
      return EmailAccount.createdAtTime(a) - EmailAccount.createdAtTime(b);
    });
  }

  public static map(item: any): EmailAccount {
    if (item instanceof EmailAccount) {
      return item;
    }
    if (item?.data) {
      return new EmailAccount(item.data);
    }
    return new EmailAccount(item);
  }

  public static mapAll(items: any): EmailAccount[] {
    if (!items) {
      return [];
    }
    const list = Array.isArray(items) ? items : [items];
    return list.filter(Boolean).map((item) => EmailAccount.map(item));
  }

  // ---------------------------------------------------------------------------
  // Smartlead
  // ---------------------------------------------------------------------------

  /**
   * Fetches an inbox from Smartlead. Throws a {@link NotFoundException} when
   * the remote inbox does not exist.
   */
  public static async fetchRemoteInbox(
    smartleadInboxId: string,
  ): Promise<SmartleadRemoteInbox> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const url = `${SMARTLEAD_API_BASE_URL}/email-accounts/${smartleadInboxId}?api_key=${apiKey}`;
    let response;
    try {
      response = await fetch(url);
    } catch (e) {
      EmailAccount.logger.error(
        `Error fetching smartlead inbox ${smartleadInboxId}: ${e}`,
      );
      throw e;
    }
    if (response?.status === 404) {
      EmailAccount.logger.error(
        `Smartlead inbox not found: ${smartleadInboxId}`,
      );
      throw new NotFoundException('Email account not found');
    }
    let remoteInbox: SmartleadRemoteInbox;
    try {
      remoteInbox = await response.json();
    } catch (e) {
      EmailAccount.logger.error(
        `Error parsing smartlead inbox ${smartleadInboxId}: ${e}`,
      );
      throw new NotFoundException('Email account not found');
    }
    if (!remoteInbox || !remoteInbox?.id) {
      EmailAccount.logger.error(
        `Smartlead inbox not found: ${smartleadInboxId}`,
      );
      throw new NotFoundException('Email account not found');
    }
    return remoteInbox;
  }

  /**
   * Lists every inbox Smartlead knows about, optionally scoped to a client.
   */
  public static async fetchAllRemoteInboxes({
    smartleadClientId,
    limit = 100,
  }: {
    smartleadClientId?: string;
    limit?: number;
  } = {}): Promise<SmartleadRemoteInbox[]> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const inboxes: SmartleadRemoteInbox[] = [];
    let offset = 0;
    // Smartlead paginates the email account listing endpoint.
    // eslint-disable-next-line no-constant-condition
    while (true) {
      const response = await fetch(
        `${SMARTLEAD_API_BASE_URL}/email-accounts/?api_key=${apiKey}&offset=${offset}&limit=${limit}`,
      );
      if (!response?.ok) {
        EmailAccount.logger.error(
          `Failed to list smartlead inboxes: ${response?.status}`,
        );
        break;
      }
      const page = await response.json();
      const pageInboxes: SmartleadRemoteInbox[] = Array.isArray(page)
        ? page
        : (page?.data ?? []);
      if (!pageInboxes?.length) {
        break;
      }
      inboxes.push(...pageInboxes);
      if (pageInboxes.length < limit) {
        break;
      }
      offset += limit;
    }
    if (smartleadClientId) {
      return inboxes.filter(
        (inbox) => String(inbox?.client_id) === String(smartleadClientId),
      );
    }
    return inboxes;
  }

  /**
   * Hydrates the creation time and warm up reputation of the inbox straight
   * from Smartlead.
   */
  public async hydrateFromSmartlead(): Promise<EmailAccount> {
    const remoteInbox = await EmailAccount.fetchRemoteInbox(
      this.smartleadInboxId,
    );
    return this.applyRemoteInbox(remoteInbox);
  }

  public applyRemoteInbox(remoteInbox: SmartleadRemoteInbox): EmailAccount {
    if (!remoteInbox) {
      return this;
    }
    this.createdAt = remoteInbox?.created_at ?? this.createdAt;
    this.warmupReputation = EmailAccount.parseDeliverabilityScore(
      remoteInbox?.warmup_details?.warmup_reputation,
    );
    if (!this.email && remoteInbox?.from_email) {
      this.email = remoteInbox.from_email;
    }
    if (!this.smartleadClientId && remoteInbox?.client_id !== undefined) {
      this.smartleadClientId =
        remoteInbox.client_id === null ? undefined : String(remoteInbox.client_id);
    }
    if (remoteInbox?.message_per_day !== undefined) {
      this.messagePerDay = remoteInbox.message_per_day;
    }
    if (remoteInbox?.tags?.length && !this.tags?.length) {
      this.tags = EmailAccount.normalizeTags(remoteInbox.tags);
    }
    return this;
  }

  // ---------------------------------------------------------------------------
  // Campaign association
  // ---------------------------------------------------------------------------

  public isAssociatedWithCampaign(campaignId: string): boolean {
    return (this.campaignIds ?? []).includes(campaignId);
  }

  /**
   * Associates the inbox with a campaign. The operation is idempotent: calling
   * it twice with the same campaign will not double count the campaign.
   */
  public associateCampaign(campaignId: string): EmailAccount {
    if (!campaignId) {
      return this;
    }
    if (!this.campaignIds) {
      this.campaignIds = [];
    }
    if (!this.isAssociatedWithCampaign(campaignId)) {
      this.campaignIds.push(campaignId);
    }
    return this;
  }

  public disassociateCampaign(campaignId: string): EmailAccount {
    this.campaignIds = (this.campaignIds ?? []).filter(
      (id) => id !== campaignId,
    );
    return this;
  }

  public addTag(tag: string): EmailAccount {
    if (!tag) {
      return this;
    }
    if (!this.tags) {
      this.tags = [];
    }
    if (!this.tags.includes(tag)) {
      this.tags.push(tag);
    }
    return this;
  }

  // ---------------------------------------------------------------------------
  // Persistence
  // ---------------------------------------------------------------------------

  /**
   * The plain object representation which is written to the datastore. The
   * derived values are included so that they can be queried on.
   */
  public toObject(): Record<string, any> {
    return {
      id: this.smartleadInboxId,
      smartleadInboxId: this.smartleadInboxId,
      smartleadClientId: this.smartleadClientId,
      email: this.email,
      domain: this.domain,
      tags: this.tags ?? [],
      campaignIds: this.campaignIds ?? [],
      numberOfCampaignAssociated: this.numberOfCampaignAssociated,
      createdAt: this.createdAt,
      warmupReputation: this.warmupReputation,
      deliverabilityScore: this.deliverabilityScore,
      deliverability: this.deliverability,
      messagePerDay: this.messagePerDay,
    };
  }

  public toJSON(): Record<string, any> {
    return this.toObject();
  }

  public async save(datastoreService: DatastoreService): Promise<EmailAccount> {
    if (!this.smartleadInboxId) {
      throw new NotFoundException('smartleadInboxId is required');
    }
    EmailAccount.logger.log(
      `Saving email account for inbox: ${this.smartleadInboxId}`,
    );
    await datastoreService.store(
      new StoreDataDto({
        data: this.toObject(),
        context: {
          documentType: documentType.EMAIL_ACCOUNT,
          uniqueId: this.smartleadInboxId,
        },
      }),
    );
    return this;
  }

  public async delete(
    datastoreService: DatastoreService,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    EmailAccount.logger.log(
      `Deleting email account for inbox: ${this.smartleadInboxId}`,
    );
    await datastoreService.remove({
      id: this.smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return {
      message: 'Deleted successfully',
      smartleadInboxId: this.smartleadInboxId,
    };
  }

  public static async findById(
    datastoreService: DatastoreService,
    smartleadInboxId: string,
  ): Promise<EmailAccount | null> {
    if (!smartleadInboxId) {
      return null;
    }
    const res = await datastoreService.getById({
      id: String(smartleadInboxId),
      documentType: documentType.EMAIL_ACCOUNT,
    });
    const data = Array.isArray(res?.data) ? res?.data[0] : res?.data;
    return data ? EmailAccount.map(data) : null;
  }

  public static async findByEmail(
    datastoreService: DatastoreService,
    email: string,
  ): Promise<EmailAccount | null> {
    if (!email) {
      return null;
    }
    const res = await datastoreService.getByField({
      fieldKey: 'data.email',
      fieldValue: email,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    const accounts = EmailAccount.mapAll(res?.data);
    return accounts?.length ? accounts[0] : null;
  }

  public static async findBySmartleadClientId(
    datastoreService: DatastoreService,
    smartleadClientId: string,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      return [];
    }
    const res = await datastoreService.getByField({
      fieldKey: 'data.smartleadClientId',
      fieldValue: String(smartleadClientId),
      documentType: documentType.EMAIL_ACCOUNT,
      pagination,
    });
    return EmailAccount.mapAll(res?.data);
  }

  public static async findAll(
    datastoreService: DatastoreService,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    const res = await datastoreService.getByField({
      fieldKey: 'data.smartleadInboxId',
      fieldValue: { $exists: true },
      documentType: documentType.EMAIL_ACCOUNT,
      pagination,
    });
    return EmailAccount.mapAll(res?.data);
  }

  public static async count(
    datastoreService: DatastoreService,
  ): Promise<number> {
    try {
      const count = await datastoreService.getPageCount({
        collection: documentType.EMAIL_ACCOUNT,
        fieldKey: 'data.smartleadInboxId',
        fieldValue: { $exists: true },
      });
      return count ?? 0;
    } catch (e) {
      EmailAccount.logger.warn(`Unable to count email accounts: ${e}`);
      return 0;
    }
  }
}

