import {
  IsArray,
  IsNumber,
  IsOptional,
  IsString,
  Min,
} from 'class-validator';

/**
 * An email account (inbox) which lives inside of Smartlead.
 *
 * The inbox is keyed by `smartleadInboxId`, everything else can be hydrated
 * from Smartlead when the account is saved.
 */
export class EmailAccountDto {
  @IsString()
  smartleadInboxId: string;

  @IsOptional()
  @IsString()
  email?: string;

  @IsOptional()
  @IsString()
  smartleadClientId?: string;

  @IsOptional()
  @IsArray()
  tags?: string[];

  @IsOptional()
  @IsArray()
  campaignIds?: string[];
}

/**
 * Used to look an inbox up, or delete it. Only the id is strictly required, but
 * an email address is accepted as a fallback.
