import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';
import { DatastoreService } from '../datastore/datastore.service';
import {
  DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
  DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  Deliverability,
  EmailAccount,
} from './entities/emailAccount.entity';

export type EmailAccountReference =
  | string
  | number
  | (Partial<EmailAccountDto> & { id?: string });

export type Pagination = { page?: number; pageSize?: number };

const DEFAULT_PAGE_SIZE = 100;

/**
 * Owns the pool of warmed up Smartlead inboxes which campaigns send from.
 */
@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  private readonly datastoreService: DatastoreService;

  constructor(@Optional() datastoreService?: DatastoreService) {
    // The datastore service is stateless (it proxies onto static datastore
    // entities) so we can safely fall back to a local instance when the module
    // graph does not provide one.
    this.datastoreService = datastoreService ?? new DatastoreService();
  }

  // ---------------------------------------------------------------------------
  // Helpers
  // ---------------------------------------------------------------------------

  private static resolveInboxId(reference: EmailAccountReference): string {
    if (reference === null || reference === undefined) {
      return undefined;
    }
    if (typeof reference === 'string' || typeof reference === 'number') {
      return String(reference);
    }
    const id = reference?.smartleadInboxId ?? reference?.id;
    return id === undefined || id === null ? undefined : String(id);
  }

  private static toPagination(
    pagination?: Pagination,
  ): { page: number; pageSize: number } | undefined {
    if (!pagination) {
      return undefined;
    }
    const { page, pageSize } = pagination;
    if (page === undefined && pageSize === undefined) {
      return undefined;
    }
    return {
      page: Number(page ?? 0),
      pageSize: Number(pageSize ?? DEFAULT_PAGE_SIZE),
    };
  }

  // ---------------------------------------------------------------------------
  // Selection
  // ---------------------------------------------------------------------------

  /**
   * Returns the best inboxes to send a campaign from.
   *
   * The size of the pool is `floor(totalEmails / days / emailsPerInboxPerDay)`
   * and the candidates for the Smartlead client are ranked by:
   *  1. deliverability score, highest first
   *  2. number of campaigns already associated, lowest first
   *  3. number of other inboxes sharing the same domain, lowest first
   *  4. inbox creation time, oldest first
   *
   * See: https://app.clickup.com/18036112/v/dc/h6dcg-8771/h6dcg-44571
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    totalNumberOfEmailsToSend,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: EmailAccountListDto): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const numberOfInboxesRequired =
      EmailAccount.calculateNumberOfInboxesRequired({
        totalNumberOfEmailsToSend,
        numberOfDaysInCampaign,
        numberOfEmailsPerInboxPerDay,
      });
    this.logger.log(
      `Campaign ${campaignId} for client ${smartleadClientId} requires ${numberOfInboxesRequired} inboxes to send ${totalNumberOfEmailsToSend} emails over ${numberOfDaysInCampaign} days`,
    );
    if (numberOfInboxesRequired <= 0) {
      return [];
    }
    const candidates = await this.getEmailAccountBySmartleadClientId(
      smartleadClientId,
    );
    if (!candidates?.length) {
      this.logger.warn(
        `No email accounts found for smartlead client: ${smartleadClientId}`,
      );
      return [];
    }
    const ranked = EmailAccount.rankByBestFit(candidates);
    if (ranked.length < numberOfInboxesRequired) {
      this.logger.warn(
        `Only ${ranked.length} inboxes available for client ${smartleadClientId}, ${numberOfInboxesRequired} were required`,
      );
    }
    return ranked.slice(0, numberOfInboxesRequired);
  }

  /**
   * How many inboxes a campaign needs.
   */
  getNumberOfInboxesRequiredForCampaign({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign = DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN,
    numberOfEmailsPerInboxPerDay = DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY,
  }: EmailAccountListDto): number {
    return EmailAccount.calculateNumberOfInboxesRequired({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
  }

  // ---------------------------------------------------------------------------
  // Campaign association
  // ---------------------------------------------------------------------------

  /**
   * Associates a set of inboxes with a campaign.
   *
   * The whole request is rejected when any of the requested inbox ids is not
   * known to us, and associating the same campaign twice is a no-op.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateEmailAccountsWithCampaignDto): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    if (!emailAccountIds || !Array.isArray(emailAccountIds)) {
      throw new BadRequestException('emailAccountIds is required');
    }
    const requestedIds = emailAccountIds
      .filter((id) => id !== null && id !== undefined)
      .map((id) => String(id))
      .filter((id, index, all) => all.indexOf(id) === index);
    if (!requestedIds.length) {
      throw new BadRequestException('emailAccountIds is required');
    }

    const accounts = await Promise.all(
      requestedIds.map(async (smartleadInboxId) => ({
        smartleadInboxId,
        account: await this.findEmailAccountById(smartleadInboxId),
      })),
    );
    const missing = accounts
      .filter(({ account }) => !account)
      .map(({ smartleadInboxId }) => smartleadInboxId);
    if (missing.length) {
      this.logger.error(
        `Cannot associate campaign ${campaignId}, unknown email accounts: ${missing.join(
          ', ',
        )}`,
      );
      throw new NotFoundException(
        `Email account not found: ${missing.join(', ')}`,
      );
    }

    return Promise.all(
      accounts.map(async ({ account }) => {
        if (account.isAssociatedWithCampaign(campaignId)) {
          this.logger.log(
            `Email account ${account.smartleadInboxId} is already associated with campaign ${campaignId}`,
          );
          return account;
        }
        account.associateCampaign(campaignId);
        return account.save(this.datastoreService);
      }),
    );
  }

  /**
   * Removes a campaign from a set of inboxes.
   */
  async disassociateEmailAccountsFromCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateEmailAccountsWithCampaignDto): Promise<EmailAccount[]> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    const accounts = await Promise.all(
      (emailAccountIds ?? []).map((id) => this.getEmailAccount(id)),
    );
    return Promise.all(
      accounts.map((account) =>
        account.disassociateCampaign(campaignId).save(this.datastoreService),
      ),
    );
  }

  // ---------------------------------------------------------------------------
  // CRUD
  // ---------------------------------------------------------------------------

  /**
   * Creates (or refreshes) an email account. The creation time and the warm up
   * reputation are always hydrated from Smartlead, which means an unknown
   * remote inbox is rejected with a not found error.
   */
  async saveEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailinfraService.resolveInboxId(emailAccount);
    if (!smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    const input: Partial<EmailAccountDto> =
      typeof emailAccount === 'object' && emailAccount !== null
        ? emailAccount
        : {};

    const remoteInbox = await EmailAccount.fetchRemoteInbox(smartleadInboxId);
    const existing = await this.findEmailAccountById(smartleadInboxId);

    const account = new EmailAccount({
      ...(existing ? existing.toObject() : {}),
      smartleadInboxId,
      email: input?.email ?? existing?.email ?? remoteInbox?.from_email,
      smartleadClientId:
        input?.smartleadClientId ??
        existing?.smartleadClientId ??
        (remoteInbox?.client_id === null || remoteInbox?.client_id === undefined
          ? undefined
          : String(remoteInbox.client_id)),
      tags: EmailAccount.normalizeTags([
        ...(existing?.tags ?? []),
        ...EmailAccount.normalizeTags(input?.tags),
      ]),
      campaignIds: EmailAccount.normalizeCampaignIds([
        ...(existing?.campaignIds ?? []),
        ...EmailAccount.normalizeCampaignIds(input?.campaignIds),
      ]),
    });
    account.applyRemoteInbox(remoteInbox);
    this.logger.log(
      `Saving email account ${account.email} (${account.smartleadInboxId}) with deliverability ${account.deliverability}`,
    );
    return account.save(this.datastoreService);
  }

  /**
   * Looks an email account up by its Smartlead inbox id.
   */
  async getEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailinfraService.resolveInboxId(emailAccount);
    if (!smartleadInboxId) {
      const email =
        typeof emailAccount === 'object' ? emailAccount?.email : undefined;
      if (email) {
        return this.getEmailAccountByEmail(email);
      }
      throw new BadRequestException('smartleadInboxId is required');
    }
    const account = await this.findEmailAccountById(smartleadInboxId);
    if (!account) {
      throw new NotFoundException(
        `Email account not found: ${smartleadInboxId}`,
      );
    }
    return account;
  }

  /**
   * Same as {@link getEmailAccount} but resolves to `null` instead of throwing.
   */
  async findEmailAccountById(
    smartleadInboxId: string | number,
  ): Promise<EmailAccount | null> {
    if (smartleadInboxId === null || smartleadInboxId === undefined) {
      return null;
    }
    return EmailAccount.findById(
      this.datastoreService,
      String(smartleadInboxId),
    );
  }

  /**
   * Lists the stored email accounts, one page at a time.
   */
  async getAllEmailAccounts(
    pagination?: Pagination,
  ): Promise<EmailAccount[]> {
    return EmailAccount.findAll(
      this.datastoreService,
      EmailinfraService.toPagination(pagination),
    );
  }

  /**
   * Paginated listing which also reports how many pages there are in total.
   */
  async listEmailAccounts(pagination?: Pagination): Promise<{
    emailAccounts: EmailAccount[];
    page: number;
    pageSize: number;
    pageCount: number;
  }> {
    const page = Number(pagination?.page ?? 0);
    const pageSize = Number(pagination?.pageSize ?? DEFAULT_PAGE_SIZE);
    const [emailAccounts, total] = await Promise.all([
      this.getAllEmailAccounts({ page, pageSize }),
      EmailAccount.count(this.datastoreService),
    ]);
    return {
      emailAccounts,
      page,
      pageSize,
      pageCount: pageSize > 0 ? Math.ceil((total ?? 0) / pageSize) : 0,
    };
  }

  /**
   * Looks an email account up by email address.
   */
  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    if (!email) {
      throw new BadRequestException('email is required');
    }
    const account = await EmailAccount.findByEmail(this.datastoreService, email);
    if (!account) {
      throw new NotFoundException(`Email account not found: ${email}`);
    }
    return account;
  }

  /**
   * Every inbox belonging to a Smartlead client.
   */
  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
    pagination?: Pagination,
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    return EmailAccount.findBySmartleadClientId(
      this.datastoreService,
      String(smartleadClientId),
      EmailinfraService.toPagination(pagination),
    );
  }

  /**
   * Alias of {@link getEmailAccountBySmartleadClientId}.
   */
  async getEmailAccountsBySmartleadClientId(
    smartleadClientId: string,
    pagination?: Pagination,
  ): Promise<EmailAccount[]> {
    return this.getEmailAccountBySmartleadClientId(
      smartleadClientId,
      pagination,
    );
  }

  /**
   * Deletes an email account.
   */
  async deleteEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<{ message: string; smartleadInboxId: string }> {
    const account = await this.getEmailAccount(emailAccount);
    return account.delete(this.datastoreService);
  }

  // ---------------------------------------------------------------------------
  // Maintenance
  // ---------------------------------------------------------------------------

  /**
   * Re-reads the warm up reputation of a stored inbox from Smartlead.
   */
  async syncEmailAccountReputation(
    emailAccount: EmailAccountReference,
  ): Promise<EmailAccount> {
    const account = await this.getEmailAccount(emailAccount);
    await account.hydrateFromSmartlead();
    return account.save(this.datastoreService);
  }

  /**
   * Re-reads the warm up reputation of every stored inbox from Smartlead.
   */
  async syncAllEmailAccountReputations(): Promise<{
    updated: number;
    failed: number;
    deliverability: Record<string, number>;
  }> {
    const accounts = await this.getAllEmailAccounts();
    const deliverability: Record<string, number> = {};
    let updated = 0;
    let failed = 0;
    for (const account of accounts ?? []) {
      try {
        await account.hydrateFromSmartlead();
        await account.save(this.datastoreService);
        updated += 1;
        const bucket = account.deliverability ?? Deliverability.Unknown;
        deliverability[bucket] = (deliverability[bucket] ?? 0) + 1;
      } catch (e) {
        failed += 1;
        this.logger.error(
          `Failed to sync reputation for inbox ${account?.smartleadInboxId}: ${e}`,
        );
      }
    }
    this.logger.log(
      `Synced ${updated} email accounts, ${failed} failed. ${JSON.stringify(
        deliverability,
      )}`,
    );
    return { updated, failed, deliverability };
  }

  /**
   * Imports every inbox Smartlead knows about into the datastore.
   */
  async importEmailAccountsFromSmartlead({
    smartleadClientId,
    tags,
  }: {
    smartleadClientId?: string;
    tags?: string[];
  } = {}): Promise<{ imported: number; failed: number }> {
    const remoteInboxes = await EmailAccount.fetchAllRemoteInboxes({
      smartleadClientId,
    });
    this.logger.log(`Importing ${remoteInboxes?.length ?? 0} smartlead inboxes`);
    let imported = 0;
    let failed = 0;
    for (const remoteInbox of remoteInboxes ?? []) {
      try {
        const existing = await this.findEmailAccountById(
          String(remoteInbox?.id),
        );
        const account = new EmailAccount({
          ...(existing ? existing.toObject() : {}),
          smartleadInboxId: String(remoteInbox?.id),
          email: existing?.email ?? remoteInbox?.from_email,
          smartleadClientId:
            existing?.smartleadClientId ??
            (remoteInbox?.client_id === null ||
            remoteInbox?.client_id === undefined
              ? smartleadClientId
              : String(remoteInbox.client_id)),
          tags: EmailAccount.normalizeTags([
            ...(existing?.tags ?? []),
            ...EmailAccount.normalizeTags(tags),
            ...EmailAccount.normalizeTags(remoteInbox?.tags),
          ]),
        });
        account.applyRemoteInbox(remoteInbox);
        await account.save(this.datastoreService);
        imported += 1;
      } catch (e) {
        failed += 1;
        this.logger.error(
          `Failed to import smartlead inbox ${remoteInbox?.id}: ${e}`,
        );
      }
    }
    return { imported, failed };
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { EmailinfraService } from './emailinfra.service';
import {
  AssociateEmailAccountsWithCampaignDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  @UseGuards(AuthGuard('api-key'))
  @Post('email-account')
  saveEmailAccount(@Body() emailAccount: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(emailAccount);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-account')
  getAllEmailAccounts(
    @Query('page') page?: string,
    @Query('pageSize') pageSize?: string,
  ) {
    return this.emailinfraService.listEmailAccounts({
      page: page === undefined ? undefined : Number(page),
      pageSize: pageSize === undefined ? undefined : Number(pageSize),
    });
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-account/email/:email')
  getEmailAccountByEmail(@Param('email') email: string) {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-account/client/:smartleadClientId')
  getEmailAccountBySmartleadClientId(
    @Param('smartleadClientId') smartleadClientId: string,
  ) {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(
      smartleadClientId,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Get('email-account/:smartleadInboxId')
  getEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.getEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Delete('email-account/:smartleadInboxId')
  deleteEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('email-account/campaign')
  associateEmailAccountsWithCampaign(
    @Body()
    associateEmailAccountsWithCampaignDto: AssociateEmailAccountsWithCampaignDto,
  ) {
    return this.emailinfraService.associateEmailAccountsWithCampaign(
      associateEmailAccountsWithCampaignDto,
    );
  }

  @UseGuards(AuthGuard('api-key'))
  @Post('email-account/best')
  getBestEmailAccountsForCampaign(
    @Body() emailAccountListDto: EmailAccountListDto,
  ) {
    return this.emailinfraService.getBestEmailAccountsForCampaign(
      emailAccountListDto,
    );
  }
}

import { Module } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraController } from './emailinfra.controller';
import { DatastoreModule } from '../datastore/datastore.module';

@Module({
  imports: [DatastoreModule],
  controllers: [EmailinfraController],
  providers: [EmailinfraService],
  exports: [EmailinfraService],
})
export class EmailinfraModule {}

import { Logger, ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { EmailinfraModule } from '../emailinfra.module';
import { EmailinfraService } from '../emailinfra.service';

/**
 * Imports every Smartlead inbox into the email account datastore.
 *
 * Usage:
 *   node dist/emailinfra/scripts/importEmailAccounts.js [smartleadClientId] [tag,tag]
 */
export async function importEmailAccounts({
  smartleadClientId,
  tags,
}: {
  smartleadClientId?: string;
  tags?: string[];
} = {}) {
  const logger = new Logger('importEmailAccounts');
  const app = await NestFactory.createApplicationContext(EmailinfraModule);
  app.useGlobalPipes(new ValidationPipe({ whitelist: true }));
  try {
    const emailinfraService = app.get(EmailinfraService);
    const result = await emailinfraService.importEmailAccountsFromSmartlead({
      smartleadClientId,
      tags,
    });
    logger.log(
      `Imported ${result.imported} email accounts, ${result.failed} failed`,
    );
    return result;
  } finally {
    await app.close();
  }
}

if (require.main === module) {
  const [smartleadClientId, tags] = process.argv.slice(2);
  importEmailAccounts({
    smartleadClientId,
    tags: tags ? tags.split(',') : undefined,
  })
    .then(() => process.exit(0))
    .catch((e) => {
      new Logger('importEmailAccounts').error(e);
      process.exit(1);
    });
}

import { Logger } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { EmailinfraModule } from '../emailinfra.module';
import { EmailinfraService } from '../emailinfra.service';

/**
 * Refreshes the warm up reputation (and therefore the deliverability) of every
 * stored inbox straight from Smartlead.
 *
 * Usage:
 *   node dist/emailinfra/scripts/syncEmailAccountReputation.js [smartleadInboxId]
 */
export async function syncEmailAccountReputation(smartleadInboxId?: string) {
  const logger = new Logger('syncEmailAccountReputation');
  const app = await NestFactory.createApplicationContext(EmailinfraModule);
  try {
    const emailinfraService = app.get(EmailinfraService);
    if (smartleadInboxId) {
      const account =
        await emailinfraService.syncEmailAccountReputation(smartleadInboxId);
      logger.log(
        `Inbox ${account.smartleadInboxId} deliverability: ${account.deliverability}`,
      );
      return account;
    }
    const result = await emailinfraService.syncAllEmailAccountReputations();
    logger.log(
      `Synced ${result.updated} email accounts, ${result.failed} failed`,
    );
    return result;
  } finally {
    await app.close();
  }
}

if (require.main === module) {
  const [smartleadInboxId] = process.argv.slice(2);
  syncEmailAccountReputation(smartleadInboxId)
    .then(() => process.exit(0))
    .catch((e) => {
      new Logger('syncEmailAccountReputation').error(e);
      process.exit(1);
    });
}

