import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { DatastoreService } from '../datastore/datastore.service';
import { documentType } from '../datastore/entites/documentType';
import {
  Deliverability,
  EmailAccount,
} from './entities/emailAccount.entity';

type StoredDocument = { id: string; data: Record<string, any> };

/**
 * A tiny in memory stand in for the datastore so the email account subsystem
 * can be exercised without mongo/redis.
 */
class InMemoryDatastoreService {
  public documents = new Map<string, StoredDocument>();

  async store({ data, context }: { data: any; context: any }) {
    const id = context?.uniqueId ?? data?.id;
    this.documents.set(id, { id, data });
    return { message: 'Data stored successfully', uniqueId: id };
  }

  async getById({ id }: { id: string }) {
    return { data: this.documents.get(id)?.data, message: 'ok' };
  }

  async getByField({
    fieldKey,
    fieldValue,
    pagination,
  }: {
    fieldKey: string;
    fieldValue: any;
    documentType?: documentType;
    pagination?: { page: number; pageSize: number };
  }) {
    const key = fieldKey.replace(/^data\./, '');
    let matches = [...this.documents.values()]
      .map((document) => document.data)
      .filter((data) => {
        if (fieldValue && fieldValue?.$exists !== undefined) {
          return (data[key] !== undefined) === fieldValue.$exists;
        }
        return data[key] === fieldValue;
      });
    if (pagination) {
      const start = pagination.page * pagination.pageSize;
      matches = matches.slice(start, start + pagination.pageSize);
    }
    return { data: matches, message: 'ok' };
  }

  async remove({ id }: { id: string }) {
    this.documents.delete(id);
    return { message: 'Data removed successfully' };
  }

  async getPageCount() {
    return this.documents.size;
  }
}

const remoteInbox = ({
  id,
  email,
  clientId = '42',
  createdAt = '2024-01-01T00:00:00.000Z',
  warmupReputation = '100%',
}: {
  id: string;
  email: string;
  clientId?: string;
  createdAt?: string;
  warmupReputation?: string | number | null;
}) => ({
  id,
  from_email: email,
  client_id: clientId,
  created_at: createdAt,
  message_per_day: 20,
  warmup_details: { warmup_reputation: warmupReputation },
});

describe('EmailinfraService', () => {
  let service: EmailinfraService;
  let datastore: InMemoryDatastoreService;
  let fetchMock: jest.Mock;

  const registerRemoteInboxes = (inboxes: Array<Record<string, any>>) => {
    fetchMock.mockImplementation(async (url: string) => {
      const match = /email-accounts\/([^?]+)\?/.exec(url);
      if (match) {
        const inbox = inboxes.find((i) => String(i.id) === match[1]);
        if (!inbox) {
          return { ok: false, status: 404, json: async () => ({}) };
        }
        return { ok: true, status: 200, json: async () => inbox };
      }
      return { ok: true, status: 200, json: async () => inboxes };
    });
  };

  beforeEach(async () => {
    datastore = new InMemoryDatastoreService();
    fetchMock = jest.fn();
    // eslint-disable-next-line
    // @ts-ignore
    global.fetch = fetchMock;

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        EmailinfraService,
        { provide: DatastoreService, useValue: datastore },
      ],
    }).compile();

    service = module.get<EmailinfraService>(EmailinfraService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('EmailAccount entity', () => {
    it('keys the account by its smartlead inbox id and derives the domain', () => {
      const account = new EmailAccount({
        smartleadInboxId: '123',
        email: 'Sales@Mail.Example.com',
        smartleadClientId: '42',
      });
      expect(account.smartleadInboxId).toBe('123');
      expect(account.id).toBe('123');
      expect(account.domain).toBe('mail.example.com');
      expect(account.smartleadClientId).toBe('42');
      expect(account.tags).toEqual([]);
      expect(account.campaignIds).toEqual([]);
      expect(account.numberOfCampaignAssociated).toBe(0);
    });

    it('exposes the number of associated campaigns', () => {
      const account = new EmailAccount({
        smartleadInboxId: '1',
        email: 'a@b.com',
        campaignIds: ['c1', 'c2'],
      });
      expect(account.numberOfCampaignAssociated).toBe(2);
      account.associateCampaign('c3');
      expect(account.numberOfCampaignAssociated).toBe(3);
      account.associateCampaign('c3');
      expect(account.numberOfCampaignAssociated).toBe(3);
    });

    it.each([
      [100, Deliverability.High],
      [99, Deliverability.Medium],
      [98, Deliverability.Medium],
      [97, Deliverability.Low],
      [95, Deliverability.Low],
      [94, Deliverability.Burned],
      [0, Deliverability.Burned],
    ])('maps a deliverability score of %s to %s', (score, expected) => {
      expect(EmailAccount.mapDeliverability(score)).toBe(expected);
      expect(
        new EmailAccount({
          smartleadInboxId: '1',
          warmupReputation: score as number,
        }).deliverability,
      ).toBe(expected);
    });

    it('maps a missing deliverability score to Unknown', () => {
      expect(EmailAccount.mapDeliverability(undefined)).toBe(
        Deliverability.Unknown,
      );
      expect(EmailAccount.mapDeliverability(null)).toBe(Deliverability.Unknown);
      expect(new EmailAccount({ smartleadInboxId: '1' }).deliverability).toBe(
        Deliverability.Unknown,
      );
    });

    it('survives a round trip through the datastore representation', () => {
      const account = new EmailAccount({
        smartleadInboxId: '1',
        email: 'a@b.com',
        smartleadClientId: '42',
        tags: ['warm'],
        campaignIds: ['c1'],
        createdAt: '2024-01-01T00:00:00.000Z',
        warmupReputation: 99,
      });
      const rehydrated = new EmailAccount(account.toObject());
      expect(rehydrated.smartleadInboxId).toBe('1');
      expect(rehydrated.domain).toBe('b.com');
      expect(rehydrated.numberOfCampaignAssociated).toBe(1);
      expect(rehydrated.deliverability).toBe(Deliverability.Medium);
      expect(rehydrated.tags).toEqual(['warm']);
    });
  });

  describe('saveEmailAccount', () => {
    it('hydrates the creation time and warm up reputation from smartlead', async () => {
      registerRemoteInboxes([
        remoteInbox({
          id: '123',
          email: 'sales@example.com',
          createdAt: '2023-05-05T10:00:00.000Z',
          warmupReputation: '98%',
        }),
      ]);

      const account = await service.saveEmailAccount({
        smartleadInboxId: '123',
        email: 'sales@example.com',
        smartleadClientId: '42',
      });

      expect(account.createdAt).toBe('2023-05-05T10:00:00.000Z');
      expect(account.warmupReputation).toBe(98);
      expect(account.deliverability).toBe(Deliverability.Medium);
      expect(account.domain).toBe('example.com');
      expect(datastore.documents.get('123').data.email).toBe(
        'sales@example.com',
      );
    });

    it('throws a not found error for an unknown remote inbox', async () => {
      registerRemoteInboxes([]);
      await expect(
        service.saveEmailAccount({
          smartleadInboxId: 'nope',
          email: 'a@b.com',
          smartleadClientId: '42',
        }),
      ).rejects.toThrow(NotFoundException);
    });

    it('does not lose campaign associations when re-saved', async () => {
      registerRemoteInboxes([
        remoteInbox({ id: '123', email: 'sales@example.com' }),
      ]);
      await service.saveEmailAccount({
        smartleadInboxId: '123',
        email: 'sales@example.com',
        smartleadClientId: '42',
      });
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['123'],
        campaignId: 'campaign-1',
      });
      const resaved = await service.saveEmailAccount({
        smartleadInboxId: '123',
      });
      expect(resaved.campaignIds).toEqual(['campaign-1']);
      expect(resaved.numberOfCampaignAssociated).toBe(1);
    });
  });

  describe('lookups', () => {
    beforeEach(async () => {
      registerRemoteInboxes([
        remoteInbox({ id: '1', email: 'one@alpha.com', clientId: '42' }),
        remoteInbox({ id: '2', email: 'two@beta.com', clientId: '42' }),
        remoteInbox({ id: '3', email: 'three@gamma.com', clientId: '99' }),
      ]);
      await service.saveEmailAccount({ smartleadInboxId: '1' });
      await service.saveEmailAccount({ smartleadInboxId: '2' });
      await service.saveEmailAccount({ smartleadInboxId: '3' });
    });

    it('finds an account by id', async () => {
      const account = await service.getEmailAccount('2');
      expect(account.email).toBe('two@beta.com');
    });

    it('throws when the account does not exist', async () => {
      await expect(service.getEmailAccount('404')).rejects.toThrow(
        NotFoundException,
      );
    });

    it('finds an account by email', async () => {
      const account = await service.getEmailAccountByEmail('three@gamma.com');
      expect(account.smartleadInboxId).toBe('3');
    });

    it('finds accounts by smartlead client', async () => {
      const accounts =
        await service.getEmailAccountBySmartleadClientId('42');
      expect(accounts.map((a) => a.smartleadInboxId).sort()).toEqual([
        '1',
        '2',
      ]);
    });

    it('lists every account, paginated', async () => {
      const all = await service.getAllEmailAccounts();
      expect(all).toHaveLength(3);

      const firstPage = await service.getAllEmailAccounts({
        page: 0,
        pageSize: 2,
      });
      expect(firstPage).toHaveLength(2);

      const secondPage = await service.getAllEmailAccounts({
        page: 1,
        pageSize: 2,
      });
      expect(secondPage).toHaveLength(1);

      const listed = await service.listEmailAccounts({ page: 0, pageSize: 2 });
      expect(listed.pageCount).toBe(2);
      expect(listed.emailAccounts).toHaveLength(2);
    });

    it('deletes an account', async () => {
      await service.deleteEmailAccount('1');
      expect(datastore.documents.has('1')).toBe(false);
      await expect(service.getEmailAccount('1')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('associateEmailAccountsWithCampaign', () => {
    beforeEach(async () => {
      registerRemoteInboxes([
        remoteInbox({ id: '1', email: 'one@alpha.com' }),
        remoteInbox({ id: '2', email: 'two@beta.com' }),
      ]);
      await service.saveEmailAccount({ smartleadInboxId: '1' });
      await service.saveEmailAccount({ smartleadInboxId: '2' });
    });

    it('is idempotent', async () => {
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1', '2'],
        campaignId: 'campaign-1',
      });
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['1', '2'],
        campaignId: 'campaign-1',
      });
      const account = await service.getEmailAccount('1');
      expect(account.campaignIds).toEqual(['campaign-1']);
      expect(account.numberOfCampaignAssociated).toBe(1);
    });

    it('rejects the request when any inbox id is missing', async () => {
      await expect(
        service.associateEmailAccountsWithCampaign({
          emailAccountIds: ['1', 'missing'],
          campaignId: 'campaign-1',
        }),
      ).rejects.toThrow(NotFoundException);
      const account = await service.getEmailAccount('1');
      expect(account.numberOfCampaignAssociated).toBe(0);
    });
  });

  describe('getBestEmailAccountsForCampaign', () => {
    it('sizes the pool with floor(total / days / perInboxPerDay)', () => {
      expect(
        EmailAccount.calculateNumberOfInboxesRequired({
          totalNumberOfEmailsToSend: 500,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        }),
      ).toBe(2);
      expect(
        EmailAccount.calculateNumberOfInboxesRequired({
          totalNumberOfEmailsToSend: 600,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        }),
      ).toBe(3);
      expect(
        EmailAccount.calculateNumberOfInboxesRequired({
          totalNumberOfEmailsToSend: 100,
        }),
      ).toBe(0);
    });

    it('ranks by deliverability, campaign count, domain spread then age', async () => {
      const inboxes = [
        // Best: perfect score, no campaigns, unique domain, oldest.
        remoteInbox({
          id: 'best',
          email: 'best@unique.com',
          createdAt: '2020-01-01T00:00:00.000Z',
          warmupReputation: '100%',
        }),
        // Same score but already used by a campaign.
        remoteInbox({
          id: 'used',
          email: 'used@other.com',
          createdAt: '2019-01-01T00:00:00.000Z',
          warmupReputation: '100%',
        }),
        // Same score, no campaigns, but shares a domain with a sibling.
        remoteInbox({
          id: 'shared-a',
          email: 'a@shared.com',
          createdAt: '2018-01-01T00:00:00.000Z',
          warmupReputation: '100%',
        }),
        remoteInbox({
          id: 'shared-b',
          email: 'b@shared.com',
          createdAt: '2018-06-01T00:00:00.000Z',
          warmupReputation: '100%',
        }),
        // Lower score, should always come last.
        remoteInbox({
          id: 'burned',
          email: 'burned@burned.com',
          createdAt: '2010-01-01T00:00:00.000Z',
          warmupReputation: '10%',
        }),
      ];
      registerRemoteInboxes(inboxes);
      for (const inbox of inboxes) {
        await service.saveEmailAccount({ smartleadInboxId: String(inbox.id) });
      }
      await service.associateEmailAccountsWithCampaign({
        emailAccountIds: ['used'],
        campaignId: 'other-campaign',
      });

      const best = await service.getBestEmailAccountsForCampaign({
        smartleadClientId: '42',
        campaignId: 'campaign-1',
        totalNumberOfEmailsToSend: 1000,
        numberOfDaysInCampaign: 10,
        numberOfEmailsPerInboxPerDay: 20,
      });

      expect(best.map((a) => a.smartleadInboxId)).toEqual([
        'best',
        'shared-a',
        'shared-b',
        'used',
        'burned',
      ]);
    });

    it('only returns as many inboxes as the campaign needs', async () => {
      const inboxes = [
        remoteInbox({ id: '1', email: 'one@a.com' }),
        remoteInbox({ id: '2', email: 'two@b.com' }),
        remoteInbox({ id: '3', email: 'three@c.com' }),
      ];
      registerRemoteInboxes(inboxes);
      for (const inbox of inboxes) {
        await service.saveEmailAccount({ smartleadInboxId: String(inbox.id) });
      }
      const best = await service.getBestEmailAccountsForCampaign({
        smartleadClientId: '42',
        campaignId: 'campaign-1',
        totalNumberOfEmailsToSend: 400,
        numberOfDaysInCampaign: 10,
        numberOfEmailsPerInboxPerDay: 20,
      });
      expect(best).toHaveLength(2);
    });
  });
});

