/**
 * Reads a single inbox from Smartlead, resolving to `null` when it does not
 * exist remotely.
 */
public static async findRemoteInbox(
  smartleadInboxId: string,
): Promise<SmartleadRemoteInbox | null> {
  const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
  const url = `${SMARTLEAD_API_BASE_URL}/email-accounts/${smartleadInboxId}?api_key=${apiKey}`;
  let response;
  try {
    response = await fetch(url);
  } catch (e) {
    EmailAccount.logger.error(
      `Error fetching smartlead inbox ${smartleadInboxId}: ${e}`,
    );
    return null;
  }
  if (response?.status === 404) {
    return null;
  }
  let payload: any;
  try {
    payload = await response.json();
  } catch (e) {
    EmailAccount.logger.error(
      `Error parsing smartlead inbox ${smartleadInboxId}: ${e}`,
    );
    return null;
  }
  return EmailAccount.pickRemoteInbox(payload, smartleadInboxId);
}

private static pickRemoteInbox(
  payload: any,
  smartleadInboxId: string,
): SmartleadRemoteInbox | null {
  if (!payload) {
    return null;
  }
  const candidates: any[] = Array.isArray(payload)
    ? payload
    : Array.isArray(payload?.data)
      ? payload.data
      : [payload];
  const match =
    candidates.find(
      (candidate) => String(candidate?.id) === String(smartleadInboxId),
    ) ?? (candidates.length === 1 ? candidates[0] : undefined);
  return match?.id ? (match as SmartleadRemoteInbox) : null;
}

private static async findRemoteInboxInListing(
  smartleadInboxId: string,
): Promise<SmartleadRemoteInbox | null> {
  try {
    const inboxes = await EmailAccount.fetchAllRemoteInboxes();
    return (
      inboxes.find(
        (inbox) => String(inbox?.id) === String(smartleadInboxId),
      ) ?? null
    );
  } catch (e) {
    EmailAccount.logger.error(
      `Error listing smartlead inboxes while looking for ${smartleadInboxId}: ${e}`,
    );
    return null;
  }
}

