private static pickRemoteInbox(
  payload: any,
  smartleadInboxId: string,
): SmartleadRemoteInbox | null {
  if (!payload) {
    return null;
  }
  const candidates: any[] = (
    Array.isArray(payload)
      ? payload
      : Array.isArray(payload?.data)
        ? payload.data
        : [payload]
  ).filter(
    (candidate) =>
      candidate &&
      typeof candidate === 'object' &&
      Object.keys(candidate).length > 0,
  );
  if (!candidates.length) {
    return null;
  }
  const match =
    candidates.find(
      (candidate) => String(candidate?.id) === String(smartleadInboxId),
    ) ?? (candidates.length === 1 ? candidates[0] : undefined);
  return match ? (match as SmartleadRemoteInbox) : null;
}

