public applyRemoteInbox(remoteInbox: SmartleadRemoteInbox): EmailAccount {
  if (!remoteInbox) {
    return this;
  }
  const remote = remoteInbox as Record<string, any>;
  this.createdAt =
    remote?.created_at ?? remote?.createdAt ?? this.createdAt;
  this.warmupReputation = EmailAccount.parseDeliverabilityScore(
    remote?.warmup_details?.warmup_reputation ??
      remote?.warmup_details?.warmupReputation ??
      remote?.warmupDetails?.warmup_reputation ??
      remote?.warmupDetails?.warmupReputation ??
      remote?.warmup_reputation ??
      remote?.warmupReputation ??
      remote?.deliverabilityScore,
  );
  if (!this.email && (remote?.from_email ?? remote?.fromEmail)) {
    this.email = remote?.from_email ?? remote?.fromEmail;
  }
  const remoteClientId = remote?.client_id ?? remote?.clientId;
  if (!this.smartleadClientId && remoteClientId !== undefined) {
    this.smartleadClientId =
      remoteClientId === null ? undefined : String(remoteClientId);
  }
  const remoteMessagePerDay = remote?.message_per_day ?? remote?.messagePerDay;
  if (remoteMessagePerDay !== undefined) {
    this.messagePerDay = remoteMessagePerDay;
  }
  if (remote?.tags?.length && !this.tags?.length) {
    this.tags = EmailAccount.normalizeTags(remote.tags);
  }
  return this;
}

