import { Test, TestingModule } from '@nestjs/testing';
import { EmailinfraController } from './emailinfra.controller';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraModule } from './emailinfra.module';

describe('EmailinfraController', () => {
  let controller: EmailinfraController;
  let service: EmailinfraService;

  beforeEach(async () => {
    const module: TestingModule = await Test.createTestingModule({
      controllers: [EmailinfraController],
      providers: [EmailinfraService],
    }).compile();

    controller = module.get<EmailinfraController>(EmailinfraController);
    service = module.get<EmailinfraService>(EmailinfraService);
  });

  it('should be defined', () => {
    expect(controller).toBeDefined();
  });

  it('resolves through the module wiring', async () => {
    const module: TestingModule = await Test.createTestingModule({
      imports: [EmailinfraModule],
    }).compile();
    expect(module.get<EmailinfraController>(EmailinfraController)).toBeDefined();
    expect(module.get<EmailinfraService>(EmailinfraService)).toBeDefined();
  });

  it('delegates to the service', async () => {
    const saveEmailAccount = jest
      .spyOn(service, 'saveEmailAccount')
      .mockResolvedValue(undefined);
    const getEmailAccount = jest
      .spyOn(service, 'getEmailAccount')
      .mockResolvedValue(undefined);
    const deleteEmailAccount = jest
      .spyOn(service, 'deleteEmailAccount')
      .mockResolvedValue(undefined);
    const associate = jest
      .spyOn(service, 'associateEmailAccountsWithCampaign')
      .mockResolvedValue(undefined);
    const getBest = jest
      .spyOn(service, 'getBestEmailAccountsForCampaign')
      .mockResolvedValue(undefined);

    await controller.saveEmailAccount({ smartleadInboxId: '1' });
    expect(saveEmailAccount).toHaveBeenCalledWith({ smartleadInboxId: '1' });

    await controller.getEmailAccount('1');
    expect(getEmailAccount).toHaveBeenCalledWith('1');

    await controller.deleteEmailAccount('1');
    expect(deleteEmailAccount).toHaveBeenCalledWith('1');

    await controller.associateEmailAccountsWithCampaign({
      emailAccountIds: ['1'],
      campaignId: 'campaign-1',
    });
    expect(associate).toHaveBeenCalledWith({
      emailAccountIds: ['1'],
      campaignId: 'campaign-1',
    });

    await controller.getBestEmailAccountsForCampaign({
      smartleadClientId: '42',
      campaignId: 'campaign-1',
      totalNumberOfEmailsToSend: 500,
    });
    expect(getBest).toHaveBeenCalled();
  });
});

